import { runComputedInitialEffect } from './computed-test-helper';
import { TestBed } from '@angular/core/testing';
import { provideZonelessChangeDetection } from '@angular/core';
import { WatchlistComponent } from './watchlist';
import { WatchlistStore } from '../watchlist-store';
import { Movie } from '../movie';

function makeMovies(): Movie[] {
  return [
    { id: 1, title: 'Movie 1', year: 2020, genre: 'Drama', watched: false },
    { id: 2, title: 'Movie 2', year: 2021, genre: 'Comedy', watched: true },
  ];
}

function setup(store: WatchlistStore) {
  const fixture = TestBed.createComponent(WatchlistComponent);
  fixture.componentInstance.store = store;
  runComputedInitialEffect();
  fixture.autoDetectChanges(true);
  return fixture;
}

function rowFor(title: string): HTMLElement {
  const rows = Array.from(document.querySelectorAll('app-watchlist li'));
  return rows.find((r) => r.textContent!.includes(title)) as HTMLElement;
}

function checkboxFor(title: string): HTMLInputElement {
  return rowFor(title).querySelector('input') as HTMLInputElement;
}

function titles(): string[] {
  return Array.from(document.querySelectorAll('app-watchlist li .title')).map(
    (el) => (el as HTMLElement).textContent!.trim()
  );
}

describe('WatchlistComponent', () => {
  let store: WatchlistStore;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [WatchlistComponent],
      providers: [provideZonelessChangeDetection()],
    });
    store = TestBed.inject(WatchlistStore);
  });

  it('renders the movies from the store', () => {
    const movies = makeMovies();
    store.movies.set(movies);
    const fixture = setup(store);
    expect(fixture.componentInstance.movies()).toEqual(movies);
  });

  it('shows the count of movies in the watchlist', () => {
    store.movies.set(makeMovies());
    setup(store);
    expect(document.querySelector('.count')?.textContent).toContain('2');
  });

  it('shows unwatched movies before watched ones', () => {
    store.movies.set([
      { id: 3, title: 'Movie 3', year: 2022, genre: 'Sci-Fi', watched: true },
      { id: 1, title: 'Movie 1', year: 2020, genre: 'Drama', watched: false },
      { id: 2, title: 'Movie 2', year: 2021, genre: 'Comedy', watched: true },
    ]);
    setup(store);
    expect(titles()).toEqual(['Movie 1', 'Movie 3', 'Movie 2']);
  });

  it('toggles a movie as watched when its checkbox is clicked', () => {
    store.movies.set(makeMovies());
    setup(store);
    checkboxFor('Movie 1').click();
    expect(store.movies().find((m) => m.id === 1)?.watched).toBe(true);
    expect(store.movies().find((m) => m.id === 2)?.watched).toBe(true);
  });

  it('toggles a movie back to unwatched when its checkbox is clicked again', () => {
    store.movies.set(makeMovies());
    setup(store);
    checkboxFor('Movie 2').click();
    expect(store.movies().find((m) => m.id === 2)?.watched).toBe(false);
    expect(store.movies().find((m) => m.id === 1)?.watched).toBe(false);
  });

  it('opens the detail page when a row is clicked', () => {
    store.movies.set(makeMovies());
    const fixture = setup(store);
    rowFor('Movie 1').click();
    expect(fixture.componentInstance.router.navigate).toHaveBeenCalledWith(
      ['/movies', 1]
    );
  });

  it('shows an empty state when the watchlist is empty', () => {
    store.mockEmpty.set(true);
    setup(store);
    fixture.detectChanges();
    expect(document.querySelector('.empty')?.textContent).toContain(
      'Your watchlist is empty'
    );
  });
});

